package io.aetheris.orchestrator.trading;
import jakarta.persistence.*;
import java.time.Instant;
@Entity @Table(name="aetheris_trading_risk_policy")
public class TradingRiskPolicyEntity {@Id @Column(length=80) private String profileKey;@Column(nullable=false) private double riskPerTradePct;@Column(nullable=false) private double maxDailyLossPct;@Column(nullable=false) private int maxLeverage;@Column(nullable=false) private double minRewardRisk;@Column(nullable=false) private Instant updatedAt;protected TradingRiskPolicyEntity(){}public TradingRiskPolicyEntity(String key){this.profileKey=key;update(.5,2,3,1.5);}public String getProfileKey(){return profileKey;}public double getRiskPerTradePct(){return riskPerTradePct;}public double getMaxDailyLossPct(){return maxDailyLossPct;}public int getMaxLeverage(){return maxLeverage;}public double getMinRewardRisk(){return minRewardRisk;}public Instant getUpdatedAt(){return updatedAt;}public void update(double risk,double daily,int leverage,double minRr){this.riskPerTradePct=Math.max(.05,Math.min(risk,2));this.maxDailyLossPct=Math.max(.25,Math.min(daily,10));this.maxLeverage=Math.max(1,Math.min(leverage,20));this.minRewardRisk=Math.max(1,Math.min(minRr,5));this.updatedAt=Instant.now();}}
